    public List<BatchClosedEventResponse> getBatchClosedEvents(
            TransactionReceipt transactionReceipt) {
        List<Contract.EventValuesWithLog> valueList = extractEventParametersWithLog(BATCHCLOSED_EVENT, transactionReceipt);
        ArrayList<BatchClosedEventResponse> responses = new ArrayList<BatchClosedEventResponse>(valueList.size());
        for (Contract.EventValuesWithLog eventValues : valueList) {
            BatchClosedEventResponse typedResponse = new BatchClosedEventResponse();
            typedResponse.log = eventValues.getLog();
            typedResponse.batchIdHash = (byte[]) eventValues.getIndexedValues().get(0).getValue();
            typedResponse.operator = (String) eventValues.getIndexedValues().get(1).getValue();
            typedResponse.status = (BigInteger) eventValues.getNonIndexedValues().get(0).getValue();
            typedResponse.reasonHash = (byte[]) eventValues.getNonIndexedValues().get(1).getValue();
            responses.add(typedResponse);
        }
        return responses;
    }

    public List<BatchRegisteredEventResponse> getBatchRegisteredEvents(
            TransactionReceipt transactionReceipt) {
        List<Contract.EventValuesWithLog> valueList = extractEventParametersWithLog(BATCHREGISTERED_EVENT, transactionReceipt);
        ArrayList<BatchRegisteredEventResponse> responses = new ArrayList<BatchRegisteredEventResponse>(valueList.size());
        for (Contract.EventValuesWithLog eventValues : valueList) {
            BatchRegisteredEventResponse typedResponse = new BatchRegisteredEventResponse();
            typedResponse.log = eventValues.getLog();
            typedResponse.batchIdHash = (byte[]) eventValues.getIndexedValues().get(0).getValue();
            typedResponse.productIdHash = (byte[]) eventValues.getIndexedValues().get(1).getValue();
            typedResponse.operator = (String) eventValues.getIndexedValues().get(2).getValue();
            typedResponse.payloadHash = (byte[]) eventValues.getNonIndexedValues().get(0).getValue();
            typedResponse.startedAt = (BigInteger) eventValues.getNonIndexedValues().get(1).getValue();
            responses.add(typedResponse);
        }
        return responses;
    }

